"""Additional final/pending/sample branches, keyboard controls and truthful save guards."""
import json
from pathlib import Path
from playwright.sync_api import sync_playwright,expect
from browser_fixture import make_fixture
OUT=Path(__file__).resolve().parent;BASE='http://127.0.0.1:5173';checks=[]
def check(name,ok):checks.append({'name':name,'passed':bool(ok)});print(name,bool(ok),flush=True)
def visit(p,path):p.goto(BASE+path);p.wait_for_load_state('networkidle')
with sync_playwright() as p:
 b=p.chromium.launch(channel='chrome',headless=True);c=b.new_context(viewport={'width':1024,'height':768});c.add_init_script("""window.MutationObserver=class{observe(){}disconnect(){}};const put=Storage.prototype.setItem;Storage.prototype.setItem=function(k,v){if(k===sessionStorage.getItem('fail-key'))throw new DOMException('blocked','QuotaExceededError');return put.call(this,k,v)}""")
 page=c.new_page();visit(page,'/sign-in');fixture=make_fixture(page)
 page.evaluate('f=>{localStorage.setItem("hm.user",JSON.stringify({phone:"901234567"}));localStorage.setItem("hm.attempts",JSON.stringify(f.attempts));localStorage.setItem("hm.sessions","{}");localStorage.setItem("hm.mistakes",JSON.stringify([f.qs[0].id]));localStorage.setItem("hm.language","uz")}',fixture)
 visit(page,'/results/final');check('All-correct result offers review without claiming mistakes',page.locator('.learning-stack>.learning-card').first.locator('a.btn').inner_text()=='Javoblarni ko‘rish')
 radios=page.locator('.learning-answers [role=radio]');radios.first.focus();page.keyboard.press('End');check('Result filter End selects last and keeps one tab stop',radios.last.get_attribute('aria-checked')=='true' and len([x for x in radios.evaluate_all('els=>els.map(e=>e.tabIndex)') if x==0])==1)
 page.keyboard.press('Home');check('Result filter Home restores all rows without losing focus',radios.first.get_attribute('aria-checked')=='true' and page.locator('.learning-question-link').count()==6)
 page.locator('.learning-question-link').first.focus();page.keyboard.press('Enter');expect(page.locator('main h1')).to_be_focused();check('Keyboard entry focuses review heading with full prompt',page.locator('.learning-review .body[lang=kaa]').count()>0)
 page.keyboard.press('ArrowRight');page.wait_for_url('**/q/2?*');expect(page.locator('main h1')).to_be_focused();check('Keyboard review step focuses new question heading',True)
 if fixture['manual']:
  visit(page,'/results/manual');check('Pending-only result offers written review as primary action',page.locator('.learning-stack>.learning-card').first.locator('a.btn').inner_text()=='Yozma javoblarni ko‘rish')
  page.evaluate('f=>{localStorage.setItem("hm.mistakes",JSON.stringify([f.manual.id]));localStorage.setItem("hm.attempts",JSON.stringify(f.attempts.filter(a=>a.id==="manual")))}',fixture);visit(page,'/mistakes');page.locator('[id^="retry-"]').click();check('Manual-only retry exposes one deliberate reveal and no claimed model',page.locator('.learning-retry .learning-models').count()==0 and page.locator('.learning-retry button.btn-primary').count()==1)
  page.locator('textarea').fill('learner response');page.locator('.learning-retry button.btn-primary').click();check('Manual retry stays pending and does not fabricate an accepted answer',page.locator('.learning-retry [role=status]').inner_text()=='Baholash kutilmoqda' and page.locator('.learning-models').count()==0)
  visit(page,'/progress');check('Pending-only history has no final average or chart',page.locator('[data-average]').inner_text()=='—' and page.locator('.learning-chart').count()==0 and page.locator('tr[data-pending]').count()==1)
 # A one-point chart is meaningful and has an exact table counterpart.
 page.evaluate('f=>localStorage.setItem("hm.attempts",JSON.stringify(f.attempts.filter(a=>a.id==="final")))',fixture);visit(page,'/progress');check('One final result displays a point and exact table row',page.locator('.learning-chart circle').count()==1 and page.locator('tbody tr').count()==1)
 page.evaluate("""f=>{const full=f.attempts.find(a=>a.id==='final');const lower={...full.answers};for(const q of f.qs.slice(0,3))lower[q.id]=q.correct==='A'?'B':'A';const history=Array.from({length:11},(_,i)=>({...full,id:'history-'+i,submittedAt:full.submittedAt+i*86400000,answers:i?lower:full.answers}));localStorage.setItem('hm.attempts',JSON.stringify(history))}""",fixture);visit(page,'/progress');check('Statistics use all finals while chart limits to recent ten',page.locator('[data-average]').inner_text()=='55 foiz' and page.locator('[data-best]').inner_text()=='100 foiz' and page.locator('.learning-chart circle').count()==10 and page.locator('tbody tr').count()==11)
 page.evaluate('f=>localStorage.setItem("hm.attempts",JSON.stringify(f.attempts.filter(a=>a.id==="summary")))',fixture);visit(page,'/progress');check('Sample-only history remains labeled and excluded from personal statistics',page.locator('[data-average]').inner_text()=='—' and page.locator('.learning-chart').count()==0 and page.locator('tbody a').count()==0)
 # A result saved before failed cleanup is durable, so sign-out must not call its answers unsaved.
 page.evaluate('f=>{localStorage.setItem("hm.attempts","[]");localStorage.setItem("hm.sessions",JSON.stringify({"practice-1":f.session}))}',fixture);visit(page,'/exam/practice-1');page.evaluate('sessionStorage.setItem("fail-key","hm.sessions")');page.locator('button.opt').first.click();page.locator('.ux-finish').click();page.locator('#submit-now').click();check('Edge setup retains one durable result after cleanup failure',page.locator('.assessment-pending').count()==1)
 page.locator('.assessment-utilities button').first.click();page.locator('dialog[open] .assessment-dialog-actions button').last.click();page.wait_for_url('**/tests/practice-1');page.locator('.focus-top a').first.click();page.wait_for_load_state('networkidle');page.locator('a[href="/profile"]').first.click();page.wait_for_url('**/profile');page.locator('#profile-signout').click();check('Durable result awaiting cleanup is not called unsaved at sign-out','Saqlangan testlar' in page.locator('dialog[open] p').inner_text())
 page.keyboard.press('Escape');page.evaluate('sessionStorage.removeItem("fail-key")');
 # Timer deadline is unchanged by a confirmed sign-out.
 page.evaluate('f=>{localStorage.setItem("hm.sessions",JSON.stringify({"mock-7":{...f.session,testId:"mock-7",mode:"mock",endsAt:Date.now()+900000}}))}',fixture);visit(page,'/profile');deadline=page.evaluate('JSON.parse(localStorage.getItem("hm.sessions"))["mock-7"].endsAt');page.locator('#profile-signout').click();page.locator('dialog[open] .learning-actions button').last.click();page.wait_for_url('**/sign-in');check('Sign-out never renews an active timed deadline',page.evaluate('JSON.parse(localStorage.getItem("hm.sessions"))["mock-7"].endsAt')==deadline)
 c.close();b.close()
(OUT/'edge-results.json').write_text(json.dumps(checks,ensure_ascii=False,indent=2),encoding='utf-8');assert all(row['passed'] for row in checks)
